{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "PubSub Topic not encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_pubsub_topic.notification_trigger",
      "severity": "MEDIUM",
      "explanation": "The PubSub topic uses Google-managed encryption keys by default. For enterprise disaster recovery orchestration, sensitive event data should be protected using Customer-Supplied Encryption Keys (CSEK) to ensure cryptographic control and compliance."
    }
  ],
  "patched_code": "resource \"google_pubsub_topic\" \"notification_trigger\" {\n  name = \"enterprise-disaster-recovery-orchestration-platform-topic-notification\"\n\n  kms_key_name = var.kms_key_self_link\n}\n\nvariable \"kms_key_self_link\" {\n  description = \"The self link of the KMS key used to encrypt the PubSub topic messages.\"\n  type        = string\n}",
  "fix_summary": "Added a `kms_key_name` attribute to the `google_pubsub_topic` resource to enable Customer-Supplied Encryption Key (CSEK) protection. Introduced a variable `kms_key_self_link` to allow flexible configuration of the specific KMS key without hardcoding values."
}
